class Api{
 static final cache=<String,Map<String,dynamic>>{};
 static Future<Map<String,dynamic>> request(String file,{bool refresh=false})async{
  if(!refresh&&cache[file]!=null)return cache[file]!;
  final c=HttpClient()..connectionTimeout=const Duration(seconds:15);
  try{final q=await c.getUrl(Uri.parse('$root/$file'));q.headers.set('accept','application/json');final r=await q.close().timeout(const Duration(seconds:25));if(r.statusCode!=200)throw HttpException('HTTP ${r.statusCode}');return cache[file]=jsonDecode(await utf8.decoder.bind(r).join());}finally{c.close();}
 }
}
class Store{
 static Future<SharedPreferences> get p=>SharedPreferences.getInstance();
 static Future<Map<String,dynamic>?> map(String k)async{final s=(await p).getString(k);return s==null?null:jsonDecode(s);}
 static Future<List<dynamic>> list(String k)async{final s=(await p).getString(k);return s==null?[]:jsonDecode(s);}
 static Future<void> set(String k,Object v)async=>(await p).setString(k,jsonEncode(v));
 static Future<void> del(String k)async=>(await p).remove(k);
}
class Data{
 final Map<String,dynamic> config;final List<Map<String,dynamic>> users,exams,tests;
 Data(this.config,this.users,this.exams,this.tests);
 static Future<Data> load({bool refresh=false})async{final v=await Future.wait(['site-main.json','users-registered.json','exams.json','tests.json'].map((x)=>Api.request(x,refresh:refresh)));return Data(v[0],List<Map<String,dynamic>>.from(v[1]['users']),List<Map<String,dynamic>>.from(v[2]['exams']),List<Map<String,dynamic>>.from(v[3]['tests']));}
}
